"use client"

import { useEffect, useMemo, useState } from "react"
import { Barcode, Boxes, Building2, ChevronLeft, ChevronRight, Eye, FileImage, ImagePlus, MoreHorizontal, Pencil, Plus, Power, Search, Trash2, Upload, X } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Textarea } from "@/components/ui/textarea"
import { formatCOP, SUPPLIERS } from "@/lib/data"
import { initialProductMaster, initialWarehouses, nextReference, PRODUCT_STORAGE_KEY, ProductMaster, WarehouseRecord, WAREHOUSE_STORAGE_KEY } from "@/lib/product-master"
import { formatPercent, markupPercent, PRODUCT_UPDATED_EVENT, readSuggestedMarkup, salePriceFromMarkup, unitProfit } from "@/lib/cost-pricing"

const lines = ["Herramientas eléctricas", "Herramientas manuales", "Ferretería", "Iluminación", "Pinturas", "Seguridad industrial", "Carpintería"]
type CatalogRecord = { id: string; name: string; parentId: string | null; active: boolean }
const CLASSIFICATION_STORAGE_KEY = "ferreia-admin-product-classifications"
const initialLines: CatalogRecord[] = lines.map((name, index) => ({ id: `LIN-${index + 1}`, name, parentId: null, active: true }))
const initialGroups: CatalogRecord[] = [
  { id: "GRP-1", name: "Herramientas", parentId: "LIN-1", active: true },
  { id: "GRP-2", name: "Accesorios y consumibles", parentId: "LIN-1", active: true },
  { id: "GRP-3", name: "Elementos de fijación", parentId: "LIN-3", active: true },
  { id: "GRP-4", name: "Luminarias", parentId: "LIN-4", active: true },
]
const initialSubgroups: CatalogRecord[] = [
  { id: "SUB-1", name: "Taladros", parentId: "GRP-1", active: true },
  { id: "SUB-2", name: "Sierras", parentId: "GRP-1", active: true },
  { id: "SUB-3", name: "Tornillería", parentId: "GRP-3", active: true },
  { id: "SUB-4", name: "Bombillos LED", parentId: "GRP-4", active: true },
]
const units = ["Unidad", "Caja", "Metro", "Kilogramo", "Litro", "Galón", "Rollo", "Par"]
type BrandRecord = { id: string; name: string; country: string; active: boolean }
const BRAND_STORAGE_KEY = "ferreia-admin-product-brands"
const initialBrands: BrandRecord[] = ["Bosch", "Truper", "Philips", "Pretul", "Stanley"].map((name, index) => ({ id: `BR-${index + 1}`, name, country: "", active: true }))
const emptyWarehouse: WarehouseRecord = { id: "", code: "", name: "", address: "", manager: "", type: "Auxiliar", active: true }
function blank(reference: string, warehouse: string): ProductMaster { return { id: `draft-${Date.now()}`, reference, supplierReference: "", name: "", sku: "", barcodes: [{ presentation: "Unidad", code: "" }, { presentation: "Inner", code: "" }, { presentation: "Master", code: "" }], line: lines[0], brand: "", group: "", subgroup: "", packaging: { inner: 1, master: 1 }, unit: "Unidad", weight: 0, cost: 0, price: 0, markupPercent: readSuggestedMarkup(), taxRate: 19, warehouse, stock: 0, stockMin: 0, stockMax: 0, images: [], suppliers: [], characteristics: "", active: true } }

export function ProductCatalogView() {
  const [products, setProducts] = useState(initialProductMaster); const [warehouses, setWarehouses] = useState(initialWarehouses)
  const [brands, setBrands] = useState(initialBrands); const [brandName, setBrandName] = useState(""); const [brandCountry, setBrandCountry] = useState("")
  const [lineCatalog, setLineCatalog] = useState(initialLines); const [groupCatalog, setGroupCatalog] = useState(initialGroups); const [subgroupCatalog, setSubgroupCatalog] = useState(initialSubgroups)
  const [query, setQuery] = useState(""); const [form, setForm] = useState<ProductMaster | null>(null); const [editingId, setEditingId] = useState<string | null>(null); const [warehouseForm, setWarehouseForm] = useState<WarehouseRecord | null>(null)
  const [viewing, setViewing] = useState<ProductMaster | null>(null)
  useEffect(() => { const p = localStorage.getItem(PRODUCT_STORAGE_KEY); const w = localStorage.getItem(WAREHOUSE_STORAGE_KEY); const b = localStorage.getItem(BRAND_STORAGE_KEY); const c = localStorage.getItem(CLASSIFICATION_STORAGE_KEY); if (p) setProducts(JSON.parse(p) as ProductMaster[]); if (w) setWarehouses(JSON.parse(w)); if (b) setBrands(JSON.parse(b)); if (c) { const data = JSON.parse(c); setLineCatalog(data.lines); setGroupCatalog(data.groups); setSubgroupCatalog(data.subgroups) } }, [])
  useEffect(() => { const reload = () => { const stored = localStorage.getItem(PRODUCT_STORAGE_KEY); setProducts(stored ? JSON.parse(stored) as ProductMaster[] : initialProductMaster) }; window.addEventListener(PRODUCT_UPDATED_EVENT, reload); window.addEventListener("storage", reload); return () => { window.removeEventListener(PRODUCT_UPDATED_EVENT, reload); window.removeEventListener("storage", reload) } }, [])
  const filtered = useMemo(() => { const q = query.toLowerCase(); return products.filter((p) => !q || [p.reference, p.supplierReference, p.name, p.sku, p.brand, ...p.barcodes.map((b) => b.code)].some((v) => v.toLowerCase().includes(q))) }, [products, query])
  function persistProducts(next: ProductMaster[]) { setProducts(next); localStorage.setItem(PRODUCT_STORAGE_KEY, JSON.stringify(next)); window.dispatchEvent(new Event(PRODUCT_UPDATED_EVENT)) }
  function persistWarehouses(next: WarehouseRecord[]) { setWarehouses(next); localStorage.setItem(WAREHOUSE_STORAGE_KEY, JSON.stringify(next)) }
  function persistBrands(next: BrandRecord[]) { setBrands(next); localStorage.setItem(BRAND_STORAGE_KEY, JSON.stringify(next)) }
  function persistClassifications(nextLines: CatalogRecord[], nextGroups: CatalogRecord[], nextSubgroups: CatalogRecord[]) { setLineCatalog(nextLines); setGroupCatalog(nextGroups); setSubgroupCatalog(nextSubgroups); localStorage.setItem(CLASSIFICATION_STORAGE_KEY, JSON.stringify({ lines: nextLines, groups: nextGroups, subgroups: nextSubgroups })) }
  function createBrand(e: React.FormEvent) { e.preventDefault(); if (!brandName.trim()) return; persistBrands([...brands, { id: `BR-${Date.now()}`, name: brandName.trim(), country: brandCountry.trim(), active: true }]); setBrandName(""); setBrandCountry("") }
  function create() { setEditingId(null); setForm(blank(nextReference(products), warehouses.find((w) => w.active)?.name ?? "")) }
  function editProduct(product: ProductMaster) { setViewing(null); setEditingId(product.id); setForm(structuredClone(product)) }
  function createFromViewer() { setViewing(null); create() }
  function saveProduct(e: React.FormEvent) { e.preventDefault(); if (!form) return; const clean = { ...form, name: form.name.trim(), sku: form.sku.trim(), barcodes: form.barcodes.filter((b) => b.code.trim()) }; persistProducts(editingId ? products.map((p) => p.id === editingId ? clean : p) : [clean, ...products]); setForm(null); setEditingId(null) }
  function saveWarehouse(e: React.FormEvent) { e.preventDefault(); if (!warehouseForm) return; const exists = warehouses.some((w) => w.id === warehouseForm.id); persistWarehouses(exists ? warehouses.map((w) => w.id === warehouseForm.id ? warehouseForm : w) : [...warehouses, { ...warehouseForm, id: `WH-${String(warehouses.length + 1).padStart(3, "0")}` }]); setWarehouseForm(null) }
  return <div className="space-y-4"><Tabs defaultValue="articulos"><div className="min-w-0 overflow-x-auto"><TabsList className="min-w-max"><TabsTrigger value="articulos">Artículos</TabsTrigger><TabsTrigger value="clasificacion">Líneas, grupos y subgrupos</TabsTrigger><TabsTrigger value="marcas">Marcas</TabsTrigger><TabsTrigger value="bodegas">Bodegas</TabsTrigger></TabsList></div>
    <TabsContent value="articulos" className="space-y-4"><div className="grid gap-3 sm:grid-cols-3"><Summary icon={Boxes} label="Artículos registrados" value={products.length} /><Summary icon={Barcode} label="Códigos de barras" value={products.reduce((s, p) => s + p.barcodes.length, 0)} /><Summary icon={Building2} label="Bodegas habilitadas" value={warehouses.filter((w) => w.active).length} /></div>
      {viewing && <ProductViewer product={viewing} close={() => setViewing(null)} edit={() => editProduct(viewing)} create={createFromViewer} />}
      {form && <ProductFormWizard form={form} setForm={setForm} warehouses={warehouses} brands={brands} lines={lineCatalog} groups={groupCatalog} subgroups={subgroupCatalog} editing={!!editingId} cancel={() => setForm(null)} submit={saveProduct} />}
      <Card><CardContent className="space-y-4 p-4"><div className="flex flex-col gap-3 lg:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input className="pl-9" placeholder="Buscar referencia, artículo, SKU, marca o código de barras..." value={query} onChange={(e) => setQuery(e.target.value)} /></div><Button onClick={create}><Plus className="mr-2 h-4 w-4" />Nuevo artículo</Button></div><div className="catalog-table-scroll min-w-0 overflow-auto rounded-lg border border-border"><Table className="min-w-max" containerClassName="overflow-visible rounded-none border-0"><TableHeader className="[&_th]:sticky [&_th]:top-0 [&_th]:z-10 [&_th]:bg-muted [&_th]:shadow-[0_1px_0_0_var(--border)]"><TableRow><TableHead>Referencia</TableHead><TableHead>Artículo</TableHead><TableHead>Clasificación</TableHead><TableHead>Empaque</TableHead><TableHead className="text-right">Costo</TableHead><TableHead className="text-right">Venta</TableHead><TableHead className="text-right">Ganancia %</TableHead><TableHead className="text-right">Ganancia / und.</TableHead><TableHead>Bodega</TableHead><TableHead>Estado</TableHead><TableHead /></TableRow></TableHeader><TableBody>{filtered.map((p) => <TableRow key={p.id} className={!p.active ? "opacity-60" : ""}><TableCell><p className="font-mono font-bold">{p.reference}</p><p className="text-xs text-muted-foreground">{p.supplierReference || "Sin ref. proveedor"}</p></TableCell><TableCell><p className="max-w-72 truncate font-medium">{p.name}</p><p className="text-xs text-muted-foreground">{p.sku} · {p.brand || "Sin marca"} · {p.barcodes.length} códigos</p>{p.costReview?.pending && <p className="mt-1 max-w-64 text-xs font-medium text-amber-700">Costo {p.costReview.newCost > p.costReview.previousCost ? "aumentó" : "disminuyó"} de {formatCOP(p.costReview.previousCost)} a {formatCOP(p.costReview.newCost)}. Revisar precio de venta.</p>}</TableCell><TableCell><p className="text-sm">{p.line}</p><p className="text-xs text-muted-foreground">{p.group} / {p.subgroup}</p></TableCell><TableCell className="text-xs">Inner {p.packaging.inner} · Master {p.packaging.master}</TableCell><ProductPricingCells product={p} /><TableCell>{p.warehouse}</TableCell><TableCell><Badge variant="secondary" className={p.active ? "bg-emerald-50 text-emerald-700" : ""}>{p.active ? "Activo" : "Inactivo"}</Badge></TableCell><TableCell><DropdownMenu><DropdownMenuTrigger render={<Button variant="ghost" size="icon" />}><MoreHorizontal className="h-4 w-4" /></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onClick={() => setViewing(p)}><Eye className="h-4 w-4" />Ver artículo</DropdownMenuItem><DropdownMenuItem onClick={() => editProduct(p)}><Pencil className="h-4 w-4" />Editar ficha</DropdownMenuItem><DropdownMenuSeparator /><DropdownMenuItem onClick={() => persistProducts(products.map((x) => x.id === p.id ? { ...x, active: !x.active } : x))}><Power className="h-4 w-4" />{p.active ? "Inactivar" : "Activar"}</DropdownMenuItem></DropdownMenuContent></DropdownMenu></TableCell></TableRow>)}</TableBody></Table></div></CardContent></Card>
    </TabsContent><TabsContent value="clasificacion"><ClassificationPanel lines={lineCatalog} groups={groupCatalog} subgroups={subgroupCatalog} persist={persistClassifications} /></TabsContent><TabsContent value="marcas"><BrandsPanel brands={brands} name={brandName} country={brandCountry} setName={setBrandName} setCountry={setBrandCountry} create={createBrand} persist={persistBrands} /></TabsContent><TabsContent value="bodegas"><WarehousePanel warehouses={warehouses} form={warehouseForm} setForm={setWarehouseForm} save={saveWarehouse} persist={persistWarehouses} /></TabsContent>
  </Tabs></div>
}

function Summary({ icon: Icon, label, value }: { icon: typeof Boxes; label: string; value: number }) { return <Card><CardContent className="flex items-center gap-3 p-4"><span className="rounded-xl bg-primary/10 p-2.5 text-primary"><Icon className="h-5 w-5" /></span><div><p className="text-xs text-muted-foreground">{label}</p><p className="text-xl font-bold">{value}</p></div></CardContent></Card> }
function ProductPricingCells({ product }: { product: ProductMaster }) {
  const profit = unitProfit(product.cost, product.price)
  return <>
    <TableCell className="text-right font-medium tabular-nums text-amber-800">{formatCOP(product.cost)}</TableCell>
    <TableCell className="text-right tabular-nums"><p className="font-bold text-emerald-700">{formatCOP(product.price)}</p><p className="text-xs text-muted-foreground">IVA {product.taxRate}%</p></TableCell>
    <TableCell className={`text-right font-semibold tabular-nums ${profit < 0 ? "text-rose-700" : "text-sky-700"}`}>{product.cost > 0 ? formatPercent(markupPercent(product.cost, product.price)) : "—"}</TableCell>
    <TableCell className={`text-right font-medium tabular-nums ${profit < 0 ? "text-rose-700" : "text-emerald-700"}`}>{formatCOP(profit)}</TableCell>
  </>
}
function Field({ label, children, wide }: { label: string; children: React.ReactNode; wide?: boolean }) { return <div className={`space-y-1.5 ${wide ? "md:col-span-2" : ""}`}><Label>{label}</Label>{children}</div> }
function Title({ number, children }: { number: string; children: React.ReactNode }) { return <div className="mb-4 flex items-center gap-2"><span className="rounded bg-primary px-2 py-1 text-xs font-bold text-primary-foreground">{number}</span><h3 className="font-semibold">{children}</h3></div> }

function ProductViewer({ product, close, edit, create }: { product: ProductMaster; close: () => void; edit: () => void; create: () => void }) {
  const details = [
    ["Referencia", product.reference], ["Código / SKU", product.sku], ["Ref. proveedor", product.supplierReference || "No registrada"],
    ["Línea", product.line], ["Marca", product.brand || "Sin marca"], ["Grupo", product.group || "Sin grupo"], ["Subgrupo", product.subgroup || "Sin subgrupo"],
    ["Unidad de medida", product.unit], ["Peso", `${product.weight} kg`], ["Embalaje", `Inner ${product.packaging.inner} · Master ${product.packaging.master}`],
    ["Costo", formatCOP(product.cost)], ["Precio de venta", formatCOP(product.price)], ["Ganancia sobre costo", product.cost > 0 ? formatPercent(markupPercent(product.cost, product.price)) : "Sin costo"], ["Ganancia por unidad", formatCOP(unitProfit(product.cost, product.price))], ["IVA", `${product.taxRate}%`],
    ["Bodega", product.warehouse], ["Stock actual", product.stock.toLocaleString("es-CO")], ["Stock mínimo", product.stockMin.toLocaleString("es-CO")], ["Stock máximo", product.stockMax.toLocaleString("es-CO")],
  ]
  return <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-6">
    <button type="button" aria-label="Cerrar detalle" className="absolute inset-0 bg-slate-950/55 backdrop-blur-[2px]" onClick={close} />
    <Card className="relative z-10 flex h-[94vh] w-full max-w-6xl flex-col overflow-hidden border-0 shadow-2xl sm:h-[min(88vh,760px)]">
      <div className="flex items-center justify-between border-b px-5 py-4 sm:px-6"><div className="flex min-w-0 items-center gap-3"><span className="rounded-xl bg-primary/10 p-2.5 text-primary"><Eye className="h-5 w-5" /></span><div className="min-w-0"><p className="truncate text-lg font-bold">{product.name}</p><p className="font-mono text-xs text-muted-foreground">Artículo {product.reference} · {product.sku}</p></div></div><Button variant="ghost" size="icon" onClick={close}><X className="h-5 w-5" /></Button></div>
      <div className="min-h-0 flex-1 overflow-y-auto px-5 py-5 sm:px-6">
        <div className="grid gap-5 lg:grid-cols-[1fr_300px]"><div className="space-y-5">
          <section><Title number="01">Información completa del artículo</Title><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{details.map(([label, value]) => <div key={label} className="rounded-lg border bg-muted/20 p-3"><p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>)}</div></section>
          <div className="grid gap-4 md:grid-cols-2"><section><p className="mb-2 font-semibold">Proveedores asociados</p><div className="space-y-2">{product.suppliers.length ? product.suppliers.map((supplier) => <div key={supplier} className="rounded-lg border p-3 text-sm">{supplier}</div>) : <p className="text-sm text-muted-foreground">Sin proveedores asociados.</p>}</div></section><section><p className="mb-2 font-semibold">Características adicionales</p><div className="min-h-24 whitespace-pre-wrap rounded-lg border p-3 text-sm text-muted-foreground">{product.characteristics || "Sin características adicionales."}</div></section></div>
          <section><p className="mb-2 font-semibold">Códigos de barras</p><div className="grid gap-2 sm:grid-cols-2">{product.barcodes.map((barcode, index) => <div key={`${barcode.code}-${index}`} className="flex items-center justify-between rounded-lg border p-3"><span className="text-xs text-muted-foreground">{barcode.presentation}</span><span className="font-mono text-sm font-semibold">{barcode.code}</span></div>)}</div></section>
        </div><aside><p className="mb-3 font-semibold">Imágenes y anexos</p><div className="grid grid-cols-2 gap-3 lg:grid-cols-1">{product.images.length ? product.images.map((src, index) => <div key={index} className="relative aspect-square overflow-hidden rounded-xl border bg-muted"><img src={src} alt={`${product.name} ${index + 1}`} className="h-full w-full object-cover" />{index === 0 && <Badge className="absolute left-2 top-2">Principal</Badge>}</div>) : <div className="col-span-full flex aspect-square flex-col items-center justify-center rounded-xl border border-dashed text-muted-foreground"><FileImage className="mb-2 h-8 w-8" /><p className="text-sm">Sin imágenes</p></div>}</div></aside></div>
      </div>
      <div className="flex items-center justify-between border-t px-5 py-4 sm:px-6"><Button variant="outline" onClick={create}><Plus className="mr-2 h-4 w-4" />Crear nuevo artículo</Button><div className="flex gap-2"><Button variant="ghost" onClick={close}>Cerrar</Button><Button onClick={edit}><Pencil className="mr-2 h-4 w-4" />Editar artículo</Button></div></div>
    </Card>
  </div>
}

type ProductFormProps = { form: ProductMaster; setForm: (p: ProductMaster) => void; warehouses: WarehouseRecord[]; brands: BrandRecord[]; lines: CatalogRecord[]; groups: CatalogRecord[]; subgroups: CatalogRecord[]; editing: boolean; cancel: () => void; submit: (e: React.FormEvent) => void }
const productSteps = [
  { value: "identificacion", label: "Identificación" },
  { value: "presentacion", label: "Presentación e inventario" },
  { value: "codigos", label: "Códigos de barras" },
  { value: "comercial", label: "Proveedores" },
  { value: "anexos", label: "Anexos" },
]

function ProductFormWizard({ form, setForm, warehouses, brands, lines, groups, subgroups, editing, cancel, submit }: ProductFormProps) {
  const [step, setStep] = useState("identificacion")
  const stepIndex = productSteps.findIndex((item) => item.value === step)
  const update = <K extends keyof ProductMaster>(key: K, value: ProductMaster[K]) => setForm({ ...form, [key]: value })
  const currentMarkup = form.markupPercent ?? markupPercent(form.cost, form.price)
  const reviewed = form.costReview ? { ...form.costReview, pending: false } : undefined
  function updateCost(cost: number) { setForm({ ...form, cost, price: salePriceFromMarkup(cost, currentMarkup), markupPercent: currentMarkup, costReview: reviewed }) }
  function updateMarkup(percent: number) { setForm({ ...form, markupPercent: percent, price: salePriceFromMarkup(form.cost, percent), costReview: reviewed }) }
  function updatePrice(price: number) { setForm({ ...form, price, markupPercent: markupPercent(form.cost, price), costReview: reviewed }) }
  async function readImages(files: FileList | null) {
    if (!files) return
    const selected = Array.from(files).slice(0, 10 - form.images.length)
    const loaded = await Promise.all(selected.map((file) => new Promise<string>((resolve) => {
      const reader = new FileReader()
      reader.onload = () => resolve(String(reader.result))
      reader.readAsDataURL(file)
    })))
    setForm({ ...form, images: [...form.images, ...loaded] })
  }
  function move(direction: number) { const target = productSteps[stepIndex + direction]; if (target) setStep(target.value) }

  return <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-6">
    <button type="button" aria-label="Cerrar ventana" className="absolute inset-0 bg-slate-950/55 backdrop-blur-[2px]" onClick={cancel} />
    <Card className="relative z-10 flex h-[94vh] w-full max-w-6xl flex-col overflow-hidden border-0 shadow-2xl sm:h-[min(88vh,760px)]">
      <div className="flex items-center justify-between border-b bg-background px-5 py-4 sm:px-6">
        <div><p className="text-lg font-bold">{editing ? `Editar artículo ${form.reference}` : "Crear nuevo artículo"}</p><p className="text-xs text-muted-foreground">Referencia automática <span className="font-mono font-bold text-foreground">{form.reference}</span></p></div>
        <Button type="button" variant="ghost" size="icon" onClick={cancel}><X className="h-5 w-5" /></Button>
      </div>
      <form onSubmit={submit} className="flex min-h-0 flex-1 flex-col">
        <Tabs value={step} onValueChange={(value) => value && setStep(value)} className="flex min-h-0 flex-1 flex-col">
          <div className="overflow-x-auto border-b bg-muted/30 px-4 py-3 sm:px-6"><TabsList className="h-auto min-w-max">
            {productSteps.map((item, index) => <TabsTrigger key={item.value} value={item.value} className="gap-2"><span className="flex h-5 w-5 items-center justify-center rounded-full bg-background text-[10px] font-bold shadow-sm">{String(index + 1).padStart(2, "0")}</span>{item.label}</TabsTrigger>)}
          </TabsList></div>
          <div className="min-h-0 flex-1 overflow-y-auto px-5 py-5 sm:px-6">
            <TabsContent value="identificacion" className="mt-0 space-y-6">
              <div><Title number="01">Identificación y clasificación</Title><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
                <Field label="Referencia automática"><Input value={form.reference} disabled className="font-mono font-bold" /></Field>
                <Field label="Nombre del artículo *" wide><Input value={form.name} onChange={(e) => update("name", e.target.value)} required /></Field>
                <Field label="Código / SKU *"><Input value={form.sku} onChange={(e) => update("sku", e.target.value)} required /></Field>
                <Field label="Ref. proveedor"><Input value={form.supplierReference} onChange={(e) => update("supplierReference", e.target.value)} /></Field>
                <Field label="Línea"><Select value={form.line} onValueChange={(value) => { if (value) setForm({ ...form, line: value, group: "", subgroup: "" }) }}><SelectTrigger><SelectValue placeholder="Selecciona una línea" /></SelectTrigger><SelectContent>{lines.filter((item) => item.active).map((item) => <SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select></Field>
                <Field label="Marca"><Select value={form.brand} onValueChange={(value) => value && update("brand", value)}><SelectTrigger><SelectValue placeholder="Selecciona una marca" /></SelectTrigger><SelectContent>{brands.filter((item) => item.active).map((item) => <SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select></Field>
                <Field label="Grupo"><Select value={form.group} onValueChange={(value) => { if (value) setForm({ ...form, group: value, subgroup: "" }) }}><SelectTrigger><SelectValue placeholder="Selecciona un grupo" /></SelectTrigger><SelectContent>{groups.filter((item) => item.active && lines.find((line) => line.id === item.parentId)?.name === form.line).map((item) => <SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select></Field>
                <Field label="Subgrupo"><Select value={form.subgroup} onValueChange={(value) => value && update("subgroup", value)}><SelectTrigger><SelectValue placeholder="Selecciona un subgrupo" /></SelectTrigger><SelectContent>{subgroups.filter((item) => item.active && groups.find((group) => group.id === item.parentId)?.name === form.group).map((item) => <SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select></Field>
              </div></div>
            </TabsContent>
            <TabsContent value="presentacion" className="mt-0"><Title number="02">Presentación, precios e inventario</Title>{form.costReview?.pending && <div className="mb-4 flex flex-wrap items-center justify-between gap-2 rounded-lg bg-amber-50 p-3 text-sm text-amber-800"><p>El costo cambió de {formatCOP(form.costReview.previousCost)} a {formatCOP(form.costReview.newCost)} en la factura {form.costReview.invoiceNumber}. Revisa el precio de venta.</p><Button type="button" size="sm" variant="outline" onClick={() => setForm({ ...form, costReview: reviewed })}>Mantener precio y aprobar revisión</Button></div>}<p className="mb-4 text-sm text-muted-foreground">La ganancia % se calcula sobre el costo: (venta − costo) ÷ costo. Al cambiar costo o porcentaje se sugiere un precio; al escribir el precio se recalcula el porcentaje.</p><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
              <Field label="Unidad de medida"><Select value={form.unit} onValueChange={(value) => value && update("unit", value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{units.map((unit) => <SelectItem key={unit} value={unit}>{unit}</SelectItem>)}</SelectContent></Select></Field>
              <Field label="Peso (kg)"><Input type="number" step="0.001" min="0" value={form.weight} onChange={(e) => update("weight", +e.target.value)} /></Field>
              <Field label="Inner (unidades)"><Input type="number" min="1" value={form.packaging.inner} onChange={(e) => update("packaging", { ...form.packaging, inner: +e.target.value })} /></Field>
              <Field label="Master (unidades)"><Input type="number" min="1" value={form.packaging.master} onChange={(e) => update("packaging", { ...form.packaging, master: +e.target.value })} /></Field>
              <Field label="Costo unitario"><Input type="number" min="0" value={form.cost} onChange={(e) => updateCost(+e.target.value)} /></Field>
              <Field label="Ganancia sobre costo (%)"><Input type="number" min="-100" max="1000" step="0.01" value={Number(currentMarkup.toFixed(2))} onChange={(e) => updateMarkup(+e.target.value)} /></Field>
              <Field label="Precio de venta *"><Input type="number" min="0" value={form.price} onChange={(e) => updatePrice(+e.target.value)} required /></Field>
              <div className="rounded-lg border bg-muted/30 p-3 text-sm"><p className="text-muted-foreground">Ganancia por unidad</p><p className="mt-1 font-bold">{formatCOP(unitProfit(form.cost, form.price))}</p></div>
              <Field label="IVA"><Select value={String(form.taxRate)} onValueChange={(value) => value && update("taxRate", +value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="0">0% / Excluido</SelectItem><SelectItem value="5">IVA 5%</SelectItem><SelectItem value="19">IVA 19%</SelectItem></SelectContent></Select></Field>
              <Field label="Bodega principal"><Select value={form.warehouse} onValueChange={(value) => value && update("warehouse", value)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{warehouses.filter((item) => item.active).map((item) => <SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select></Field>
              <Field label="Stock inicial"><Input type="number" min="0" value={form.stock} onChange={(e) => update("stock", +e.target.value)} /></Field><Field label="Stock mínimo"><Input type="number" min="0" value={form.stockMin} onChange={(e) => update("stockMin", +e.target.value)} /></Field><Field label="Stock máximo"><Input type="number" min="0" value={form.stockMax} onChange={(e) => update("stockMax", +e.target.value)} /></Field>
            </div></TabsContent>
            <TabsContent value="codigos" className="mt-0"><Title number="03">Códigos de barras</Title><div className="space-y-3">{form.barcodes.map((barcode, index) => <div key={index} className="grid gap-2 sm:grid-cols-[180px_1fr_40px]"><Select value={barcode.presentation} onValueChange={(value) => { if (!value) return; const next = [...form.barcodes]; next[index] = { ...barcode, presentation: value as typeof barcode.presentation }; update("barcodes", next) }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Unidad", "Inner", "Master", "Alterno"].map((value) => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select><Input value={barcode.code} onChange={(e) => { const next = [...form.barcodes]; next[index] = { ...barcode, code: e.target.value }; update("barcodes", next) }} placeholder="Código de barras" /><Button type="button" variant="ghost" size="icon" onClick={() => update("barcodes", form.barcodes.filter((_, itemIndex) => itemIndex !== index))}><Trash2 className="h-4 w-4" /></Button></div>)}<Button type="button" variant="outline" size="sm" onClick={() => update("barcodes", [...form.barcodes, { presentation: "Alterno", code: "" }])} disabled={form.barcodes.length >= 10}><Plus className="mr-2 h-4 w-4" />Agregar código</Button></div></TabsContent>
            <TabsContent value="comercial" className="mt-0"><Title number="04">Proveedores y características</Title><div className="grid gap-5 lg:grid-cols-2"><div className="space-y-2"><Label>Proveedores del producto</Label>{SUPPLIERS.map((supplier) => <label key={supplier.id} className="flex cursor-pointer items-center gap-3 rounded-lg border p-3 text-sm"><input type="checkbox" checked={form.suppliers.includes(supplier.nombre)} onChange={(e) => update("suppliers", e.target.checked ? [...form.suppliers, supplier.nombre] : form.suppliers.filter((value) => value !== supplier.nombre))} /><span><b>{supplier.nombre}</b><small className="block text-muted-foreground">{supplier.nit}</small></span></label>)}</div><Field label="Características adicionales"><Textarea rows={10} value={form.characteristics} onChange={(e) => update("characteristics", e.target.value)} placeholder="Material, color, dimensiones, compatibilidad, garantía..." /></Field></div></TabsContent>
            <TabsContent value="anexos" className="mt-0"><Title number="05">Anexos e imágenes</Title><div className="rounded-xl border border-dashed p-6"><label className="flex cursor-pointer flex-col items-center justify-center gap-3 py-8 text-center"><span className="rounded-full bg-primary/10 p-4 text-primary"><Upload className="h-7 w-7" /></span><div><p className="font-semibold">Seleccionar imágenes del producto</p><p className="mt-1 text-xs text-muted-foreground">Puedes cargar varias imágenes JPG, PNG o WEBP; máximo 10 archivos.</p></div><input className="hidden" type="file" multiple accept="image/*" onChange={(e) => readImages(e.target.files)} /></label></div><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-5">{form.images.map((src, index) => <div key={index} className="group relative aspect-square overflow-hidden rounded-xl border bg-muted"><img src={src} alt={`Anexo ${index + 1}`} className="h-full w-full object-cover" /><div className="absolute inset-x-0 bottom-0 bg-slate-950/65 px-2 py-1 text-[10px] text-white">Imagen {index + 1}{index === 0 ? " · Principal" : ""}</div><button type="button" className="absolute right-2 top-2 rounded-full bg-background/90 p-1.5 opacity-0 shadow group-hover:opacity-100" onClick={() => update("images", form.images.filter((_, itemIndex) => itemIndex !== index))}><Trash2 className="h-3.5 w-3.5 text-rose-600" /></button></div>)}{!form.images.length && <div className="col-span-full flex flex-col items-center py-8 text-muted-foreground"><FileImage className="mb-2 h-8 w-8" /><p className="text-sm">Aún no hay imágenes anexadas.</p></div>}</div></TabsContent>
          </div>
        </Tabs>
        <div className="flex items-center justify-between border-t bg-background px-5 py-4 sm:px-6"><Button type="button" variant="outline" onClick={() => move(-1)} disabled={stepIndex === 0}><ChevronLeft className="mr-2 h-4 w-4" />Anterior</Button><div className="hidden text-xs text-muted-foreground sm:block">Paso {stepIndex + 1} de {productSteps.length}</div><div className="flex gap-2"><Button type="button" variant="ghost" onClick={cancel}>Cancelar</Button>{stepIndex < productSteps.length - 1 ? <Button type="button" onClick={() => move(1)}>Siguiente<ChevronRight className="ml-2 h-4 w-4" /></Button> : <Button type="submit">{editing ? "Guardar cambios" : "Crear artículo"}</Button>}</div></div>
      </form>
    </Card>
  </div>
}

function ProductForm({ form, setForm, warehouses, brands, lines, groups, subgroups, editing, cancel, submit }: { form: ProductMaster; setForm: (p: ProductMaster) => void; warehouses: WarehouseRecord[]; brands: BrandRecord[]; lines: CatalogRecord[]; groups: CatalogRecord[]; subgroups: CatalogRecord[]; editing: boolean; cancel: () => void; submit: (e: React.FormEvent) => void }) {
  const update = <K extends keyof ProductMaster>(key: K, value: ProductMaster[K]) => setForm({ ...form, [key]: value })
  function images(files: FileList | null) { if (!files) return; Array.from(files).slice(0, 5 - form.images.length).forEach((file) => { const reader = new FileReader(); reader.onload = () => update("images", [...form.images, String(reader.result)]); reader.readAsDataURL(file) }) }
  return <Card className="border-accent/40"><div className="flex items-center justify-between border-b px-5 py-4"><div><p className="font-semibold">{editing ? `Editar artículo ${form.reference}` : `Nuevo artículo · Referencia ${form.reference}`}</p><p className="text-xs text-muted-foreground">Referencia consecutiva, automática y no editable.</p></div><Button variant="ghost" size="icon" onClick={cancel}><X className="h-4 w-4" /></Button></div><CardContent className="p-5"><form onSubmit={submit} className="space-y-6">
    <section><Title number="01">Identificación y clasificación</Title><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Field label="Referencia automática"><Input value={form.reference} disabled className="font-mono font-bold" /></Field><Field label="Nombre del artículo *" wide><Input value={form.name} onChange={(e) => update("name", e.target.value)} required /></Field><Field label="Código / SKU *"><Input value={form.sku} onChange={(e) => update("sku", e.target.value)} required /></Field><Field label="Ref. proveedor"><Input value={form.supplierReference} onChange={(e) => update("supplierReference", e.target.value)} /></Field><Field label="Línea"><Select value={form.line} onValueChange={(v) => { if (v) setForm({ ...form, line: v, group: "", subgroup: "" }) }}><SelectTrigger><SelectValue placeholder="Selecciona una línea" /></SelectTrigger><SelectContent>{lines.filter((item) => item.active).map((item) => <SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select></Field><Field label="Marca"><Select value={form.brand} onValueChange={(v) => v && update("brand", v)}><SelectTrigger><SelectValue placeholder="Selecciona una marca" /></SelectTrigger><SelectContent>{brands.filter((brand) => brand.active).map((brand) => <SelectItem key={brand.id} value={brand.name}>{brand.name}</SelectItem>)}</SelectContent></Select></Field><Field label="Grupo"><Select value={form.group} onValueChange={(v) => { if (v) setForm({ ...form, group: v, subgroup: "" }) }}><SelectTrigger><SelectValue placeholder="Selecciona un grupo" /></SelectTrigger><SelectContent>{groups.filter((item) => item.active && lines.find((line) => line.id === item.parentId)?.name === form.line).map((item) => <SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select></Field><Field label="Subgrupo"><Select value={form.subgroup} onValueChange={(v) => v && update("subgroup", v)}><SelectTrigger><SelectValue placeholder="Selecciona un subgrupo" /></SelectTrigger><SelectContent>{subgroups.filter((item) => item.active && groups.find((group) => group.id === item.parentId)?.name === form.group).map((item) => <SelectItem key={item.id} value={item.name}>{item.name}</SelectItem>)}</SelectContent></Select></Field></div></section>
    <section><Title number="02">Presentación, precios e inventario</Title><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Field label="Unidad de medida"><Select value={form.unit} onValueChange={(v) => v && update("unit", v)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{units.map((v) => <SelectItem key={v} value={v}>{v}</SelectItem>)}</SelectContent></Select></Field><Field label="Peso (kg)"><Input type="number" step="0.001" min="0" value={form.weight} onChange={(e) => update("weight", +e.target.value)} /></Field><Field label="Inner (unidades)"><Input type="number" min="1" value={form.packaging.inner} onChange={(e) => update("packaging", { ...form.packaging, inner: +e.target.value })} /></Field><Field label="Master (unidades)"><Input type="number" min="1" value={form.packaging.master} onChange={(e) => update("packaging", { ...form.packaging, master: +e.target.value })} /></Field><Field label="Costo"><Input type="number" min="0" value={form.cost} onChange={(e) => update("cost", +e.target.value)} /></Field><Field label="Precio de venta *"><Input type="number" min="0" value={form.price} onChange={(e) => update("price", +e.target.value)} required /></Field><Field label="IVA"><Select value={String(form.taxRate)} onValueChange={(v) => v && update("taxRate", +v)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="0">0% / Excluido</SelectItem><SelectItem value="5">IVA 5%</SelectItem><SelectItem value="19">IVA 19%</SelectItem></SelectContent></Select></Field><Field label="Bodega principal"><Select value={form.warehouse} onValueChange={(v) => v && update("warehouse", v)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{warehouses.filter((w) => w.active).map((w) => <SelectItem key={w.id} value={w.name}>{w.name}</SelectItem>)}</SelectContent></Select></Field><Field label="Stock inicial"><Input type="number" min="0" value={form.stock} onChange={(e) => update("stock", +e.target.value)} /></Field><Field label="Stock mínimo"><Input type="number" min="0" value={form.stockMin} onChange={(e) => update("stockMin", +e.target.value)} /></Field><Field label="Stock máximo"><Input type="number" min="0" value={form.stockMax} onChange={(e) => update("stockMax", +e.target.value)} /></Field></div></section>
    <section><Title number="03">Códigos de barras</Title><div className="space-y-2">{form.barcodes.map((b, i) => <div key={i} className="grid gap-2 sm:grid-cols-[160px_1fr_40px]"><Select value={b.presentation} onValueChange={(v) => { const n = [...form.barcodes]; n[i] = { ...b, presentation: v as typeof b.presentation }; update("barcodes", n) }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["Unidad", "Inner", "Master", "Alterno"].map((v) => <SelectItem key={v} value={v}>{v}</SelectItem>)}</SelectContent></Select><Input value={b.code} onChange={(e) => { const n = [...form.barcodes]; n[i] = { ...b, code: e.target.value }; update("barcodes", n) }} placeholder="Código de barras" /><Button type="button" variant="ghost" size="icon" onClick={() => update("barcodes", form.barcodes.filter((_, x) => x !== i))}><Trash2 className="h-4 w-4" /></Button></div>)}<Button type="button" size="sm" variant="outline" onClick={() => update("barcodes", [...form.barcodes, { presentation: "Alterno", code: "" }])} disabled={form.barcodes.length >= 10}><Plus className="mr-2 h-4 w-4" />Agregar código</Button></div></section>
    <section><Title number="04">Proveedores, imágenes y características</Title><div className="grid gap-5 lg:grid-cols-2"><div className="space-y-2"><Label>Proveedores del producto</Label>{SUPPLIERS.map((s) => <label key={s.id} className="flex cursor-pointer items-center gap-3 rounded-lg border p-3 text-sm"><input type="checkbox" checked={form.suppliers.includes(s.nombre)} onChange={(e) => update("suppliers", e.target.checked ? [...form.suppliers, s.nombre] : form.suppliers.filter((v) => v !== s.nombre))} /><span><b>{s.nombre}</b><small className="block text-muted-foreground">{s.nit}</small></span></label>)}</div><div className="space-y-3"><Label>Imágenes del artículo (máximo 5)</Label><label className="flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed p-5 text-sm text-muted-foreground"><Upload className="h-5 w-5" />Cargar imágenes<input className="hidden" type="file" multiple accept="image/*" onChange={(e) => images(e.target.files)} /></label><div className="grid grid-cols-5 gap-2">{form.images.map((src, i) => <div key={i} className="relative aspect-square overflow-hidden rounded-lg border"><img src={src} alt="Artículo" className="h-full w-full object-cover" /><button type="button" className="absolute right-1 top-1 rounded bg-background p-1" onClick={() => update("images", form.images.filter((_, x) => x !== i))}><X className="h-3 w-3" /></button></div>)}{!form.images.length && <span className="col-span-5 flex items-center gap-2 text-xs text-muted-foreground"><ImagePlus className="h-4 w-4" />Sin imágenes</span>}</div><Field label="Características adicionales"><Textarea rows={5} value={form.characteristics} onChange={(e) => update("characteristics", e.target.value)} placeholder="Material, color, dimensiones, compatibilidad, garantía..." /></Field></div></div></section>
    <div className="flex justify-end gap-2 border-t pt-4"><Button type="button" variant="outline" onClick={cancel}>Cancelar</Button><Button type="submit">{editing ? "Guardar cambios" : "Crear artículo"}</Button></div></form></CardContent></Card>
}

function ClassificationPanel({ lines, groups, subgroups, persist }: { lines: CatalogRecord[]; groups: CatalogRecord[]; subgroups: CatalogRecord[]; persist: (lines: CatalogRecord[], groups: CatalogRecord[], subgroups: CatalogRecord[]) => void }) {
  const [lineName, setLineName] = useState(""); const [groupName, setGroupName] = useState(""); const [subgroupName, setSubgroupName] = useState("")
  const [lineParent, setLineParent] = useState(lines.find((item) => item.active)?.id ?? ""); const [groupParent, setGroupParent] = useState(groups.find((item) => item.active)?.id ?? "")
  function addLine(e: React.FormEvent) { e.preventDefault(); if (!lineName.trim()) return; persist([...lines, { id: `LIN-${Date.now()}`, name: lineName.trim(), parentId: null, active: true }], groups, subgroups); setLineName("") }
  function addGroup(e: React.FormEvent) { e.preventDefault(); if (!groupName.trim() || !lineParent) return; persist(lines, [...groups, { id: `GRP-${Date.now()}`, name: groupName.trim(), parentId: lineParent, active: true }], subgroups); setGroupName("") }
  function addSubgroup(e: React.FormEvent) { e.preventDefault(); if (!subgroupName.trim() || !groupParent) return; persist(lines, groups, [...subgroups, { id: `SUB-${Date.now()}`, name: subgroupName.trim(), parentId: groupParent, active: true }]); setSubgroupName("") }
  return <div className="grid gap-4 xl:grid-cols-3">
    <CatalogColumn title="Líneas" description="Clasificación principal del artículo" name={lineName} setName={setLineName} submit={addLine} items={lines} parentLabel={() => "Nivel principal"} toggle={(id) => persist(lines.map((item) => item.id === id ? { ...item, active: !item.active } : item), groups, subgroups)} />
    <CatalogColumn title="Grupos" description="Agrupaciones dependientes de una línea" name={groupName} setName={setGroupName} submit={addGroup} items={groups} parentLabel={(item) => lines.find((line) => line.id === item.parentId)?.name ?? "Sin línea"} parent={<Select value={lineParent} onValueChange={(v) => v && setLineParent(v)}><SelectTrigger><SelectValue placeholder="Línea padre" /></SelectTrigger><SelectContent>{lines.filter((item) => item.active).map((item) => <SelectItem key={item.id} value={item.id}>{item.name}</SelectItem>)}</SelectContent></Select>} toggle={(id) => persist(lines, groups.map((item) => item.id === id ? { ...item, active: !item.active } : item), subgroups)} />
    <CatalogColumn title="Subgrupos" description="Último nivel de clasificación" name={subgroupName} setName={setSubgroupName} submit={addSubgroup} items={subgroups} parentLabel={(item) => groups.find((group) => group.id === item.parentId)?.name ?? "Sin grupo"} parent={<Select value={groupParent} onValueChange={(v) => v && setGroupParent(v)}><SelectTrigger><SelectValue placeholder="Grupo padre" /></SelectTrigger><SelectContent>{groups.filter((item) => item.active).map((item) => <SelectItem key={item.id} value={item.id}>{item.name}</SelectItem>)}</SelectContent></Select>} toggle={(id) => persist(lines, groups, subgroups.map((item) => item.id === id ? { ...item, active: !item.active } : item))} />
  </div>
}

function CatalogColumn({ title, description, name, setName, submit, items, parent, parentLabel, toggle }: { title: string; description: string; name: string; setName: (value: string) => void; submit: (e: React.FormEvent) => void; items: CatalogRecord[]; parent?: React.ReactNode; parentLabel: (item: CatalogRecord) => string; toggle: (id: string) => void }) {
  return <Card><CardContent className="space-y-4 p-5"><div><p className="font-semibold">{title}</p><p className="text-xs text-muted-foreground">{description}</p></div><form onSubmit={submit} className="space-y-2">{parent}<div className="flex gap-2"><Input value={name} onChange={(e) => setName(e.target.value)} placeholder={`Nueva ${title.toLowerCase().replace(/s$/, "")}`} required /><Button size="icon"><Plus className="h-4 w-4" /></Button></div></form><div className="space-y-2 border-t pt-4">{items.map((item) => <div key={item.id} className={`flex items-center justify-between rounded-lg border p-3 ${!item.active ? "opacity-55" : ""}`}><div><p className="text-sm font-medium">{item.name}</p><p className="text-[11px] text-muted-foreground">{parentLabel(item)}</p></div><Button variant="ghost" size="icon" onClick={() => toggle(item.id)}><Power className="h-4 w-4" /></Button></div>)}</div></CardContent></Card>
}

function BrandsPanel({ brands, name, country, setName, setCountry, create, persist }: { brands: BrandRecord[]; name: string; country: string; setName: (v: string) => void; setCountry: (v: string) => void; create: (e: React.FormEvent) => void; persist: (brands: BrandRecord[]) => void }) {
  return <div className="grid gap-4 lg:grid-cols-[340px_1fr]"><Card><CardContent className="p-5"><form onSubmit={create} className="space-y-4"><div><p className="font-semibold">Nueva marca</p><p className="text-sm text-muted-foreground">Crea marcas disponibles en la ficha de artículos.</p></div><Field label="Nombre de la marca *"><Input value={name} onChange={(e) => setName(e.target.value)} placeholder="Ej. DeWalt" required /></Field><Field label="País de origen"><Input value={country} onChange={(e) => setCountry(e.target.value)} placeholder="Ej. Estados Unidos" /></Field><Button className="w-full"><Plus className="mr-2 h-4 w-4" />Crear marca</Button></form></CardContent></Card><Card className="overflow-hidden"><div className="border-b px-5 py-4"><p className="font-semibold">Marcas registradas</p><p className="text-xs text-muted-foreground">{brands.filter((brand) => brand.active).length} marcas activas</p></div><Table><TableHeader><TableRow><TableHead>Marca</TableHead><TableHead>País</TableHead><TableHead>Estado</TableHead><TableHead className="text-right">Artículos</TableHead><TableHead /></TableRow></TableHeader><TableBody>{brands.map((brand) => <TableRow key={brand.id} className={!brand.active ? "opacity-60" : ""}><TableCell className="font-semibold">{brand.name}</TableCell><TableCell>{brand.country || "No especificado"}</TableCell><TableCell><Badge variant="secondary" className={brand.active ? "bg-emerald-50 text-emerald-700" : ""}>{brand.active ? "Activa" : "Inactiva"}</Badge></TableCell><TableCell className="text-right">—</TableCell><TableCell><Button variant="ghost" size="icon" onClick={() => persist(brands.map((item) => item.id === brand.id ? { ...item, active: !item.active } : item))}><Power className="h-4 w-4" /></Button></TableCell></TableRow>)}</TableBody></Table></Card></div>
}

function WarehousePanel({ warehouses, form, setForm, save, persist }: { warehouses: WarehouseRecord[]; form: WarehouseRecord | null; setForm: (w: WarehouseRecord | null) => void; save: (e: React.FormEvent) => void; persist: (w: WarehouseRecord[]) => void }) { return <div className="space-y-4">{form && <Card><CardContent className="p-5"><form onSubmit={save} className="grid gap-4 md:grid-cols-2 lg:grid-cols-3"><Field label="Código *"><Input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} required /></Field><Field label="Nombre *"><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required /></Field><Field label="Tipo"><Select value={form.type} onValueChange={(v) => v && setForm({ ...form, type: v as WarehouseRecord["type"] })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="Principal">Principal</SelectItem><SelectItem value="Auxiliar">Auxiliar</SelectItem><SelectItem value="Punto de venta">Punto de venta</SelectItem></SelectContent></Select></Field><Field label="Dirección"><Input value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} /></Field><Field label="Responsable"><Input value={form.manager} onChange={(e) => setForm({ ...form, manager: e.target.value })} /></Field><div className="flex items-end gap-2"><Button type="button" variant="outline" onClick={() => setForm(null)}>Cancelar</Button><Button>Guardar</Button></div></form></CardContent></Card>}<Card><div className="flex items-center justify-between border-b px-5 py-4"><div><p className="font-semibold">Administración de bodegas</p><p className="text-xs text-muted-foreground">Ubicaciones habilitadas para controlar las existencias</p></div><Button onClick={() => setForm({ ...emptyWarehouse })}><Plus className="mr-2 h-4 w-4" />Nueva bodega</Button></div><div className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>Código</TableHead><TableHead>Bodega</TableHead><TableHead>Tipo</TableHead><TableHead>Dirección</TableHead><TableHead>Responsable</TableHead><TableHead>Estado</TableHead><TableHead /></TableRow></TableHeader><TableBody>{warehouses.map((w) => <TableRow key={w.id}><TableCell className="font-mono font-semibold">{w.code}</TableCell><TableCell className="font-medium">{w.name}</TableCell><TableCell><Badge variant="outline">{w.type}</Badge></TableCell><TableCell>{w.address}</TableCell><TableCell>{w.manager}</TableCell><TableCell><Badge variant="secondary" className={w.active ? "bg-emerald-50 text-emerald-700" : ""}>{w.active ? "Activa" : "Inactiva"}</Badge></TableCell><TableCell><div className="flex gap-1"><Button variant="ghost" size="icon" onClick={() => setForm(w)}><Pencil className="h-4 w-4" /></Button><Button variant="ghost" size="icon" onClick={() => persist(warehouses.map((x) => x.id === w.id ? { ...x, active: !x.active } : x))}><Power className="h-4 w-4" /></Button></div></TableCell></TableRow>)}</TableBody></Table></div></Card></div> }





